import json,pathlib,unittest
from client import render_page
ROOT=pathlib.Path(__file__).resolve().parents[1]
class ClientTests(unittest.TestCase):
 def test_current_payload(self):
  self.assertEqual(render_page(json.loads((ROOT/'payload.json').read_text())),{'rows':[{'id':1}],'count':1})
 def test_empty(self):
  self.assertEqual(render_page({'data':{'rows':[]},'meta':{'total':0}}),{'rows':[],'count':0})
 def test_total_not_page_length(self):
  self.assertEqual(render_page({'data':{'rows':[{'id':5}]},'meta':{'total':23}}),{'rows':[{'id':5}],'count':23})

